const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
const dateLabel=s=>new Date(s+'T12:00:00').toLocaleDateString('fr-FR',{weekday:'long',day:'numeric',month:'long'});
const num=n=>Math.max(0,Number(n)||0), round=n=>Math.round(num(n));
const defaultPlan=()=>({name:'Découverte salle · 3 séances',sessions:[
 {name:'Séance A · Haut du corps',duration:55,exercises:[['Tirage vertical à la poulie',3,'10–12','90 s'],['Développé poitrine machine',3,'10–12','90 s'],['Rowing assis machine',3,'10–12','90 s'],['Développé épaules machine',2,'10–12','90 s'],['Curl biceps',2,'10–15','60 s'],['Extension triceps poulie',2,'10–15','60 s']]},
 {name:'Séance B · Bas du corps',duration:55,exercises:[['Presse à cuisses',3,'10–12','120 s'],['Leg curl assis',3,'10–12','90 s'],['Leg extension',2,'10–12','90 s'],['Hip thrust machine',3,'10–12','90 s'],['Mollets à la machine',3,'12–15','60 s'],['Gainage',2,'20–40 s','60 s']]},
 {name:'Séance C · Corps entier',duration:55,exercises:[['Presse à cuisses',3,'10–12','120 s'],['Développé poitrine machine',3,'10–12','90 s'],['Tirage horizontal',3,'10–12','90 s'],['Leg curl assis',2,'10–12','90 s'],['Élévations latérales',2,'12–15','60 s'],['Crunch machine ou au sol',2,'12–15','60 s']]}
]});
